package com.hoteluq.controller;
import com.hoteluq.model.*;import com.hoteluq.model.enums.*;import com.hoteluq.repository.*;import com.hoteluq.service.*;import com.hoteluq.pattern.creational.*;import com.hoteluq.pattern.structural.*;import com.hoteluq.pattern.behavioral.Observer.*;import java.time.LocalDate;import java.util.*;
public class HotelController {private final RoomRepository rooms=new RoomRepository();private final ReservationRepository reservations=new ReservationRepository();private final ReservationService reservationService=new ReservationService(reservations);private final User admin=new User("Administrador","admin@hoteluq.com",Role.ADMIN);private final User client=new User("Cliente Demo","cliente@hoteluq.com",Role.CLIENT);private final Wallet wallet=new Wallet();public HotelController(){RoomFactory f=new RoomFactory();rooms.save(f.create(RoomType.STANDARD,"101"));rooms.save(f.create(RoomType.FAMILY,"201"));rooms.save(f.create(RoomType.SUITE,"301"));wallet.topUp(3000000,"Saldo inicial demo");reservationService.addObserver(new EmailNotificationObserver());}public List<Room> rooms(){return rooms.findAll();}public Reservation createDemoReservation(String roomNumber,LocalDate in,LocalDate out){Room room=rooms.findById(roomNumber).orElseThrow();ReservationFacade facade=new ReservationFacade(reservationService);return facade.book(client,room,in,out,List.of(new AdditionalService("Desayuno",35000,true)),new WalletPaymentAdapter(wallet));}public List<Reservation> reservations(){return reservationService.all();}public Wallet wallet(){return wallet;}public User admin(){return admin;}public User client(){return client;}public ReservationService reservationService(){return reservationService;}}
